-- ═════════════════════════════════════════════════════════════════════════════
-- 3) Descuentos que siguen con cantidad distinta a la del artículo de encima.
--    Debe devolver solo las líneas de las 2 facturas con error (o ninguna fila).
--    Usa LAG para comparar cada descuento con la línea anterior de la factura.
-- ═════════════════════════════════════════════════════════════════════════════
SELECT x.factura, x.linea, x.descuento, x.cant_descuento, x.articulo_anterior, x.cant_articulo
FROM (
    SELECT
        t.tranid                                   AS factura,
        tl.id                                      AS linea,
        BUILTIN.DF(tl.item)                        AS descuento,
        it.itemtype                                AS tipo,
        ABS(tl.quantity)                           AS cant_descuento,
        LAG(BUILTIN.DF(tl.item)) OVER (PARTITION BY tl.transaction ORDER BY tl.linesequencenumber) AS articulo_anterior,
        LAG(ABS(tl.quantity))    OVER (PARTITION BY tl.transaction ORDER BY tl.linesequencenumber) AS cant_articulo
